def evolved_pp_send_recv(activations, src_stage, half, M, rank, world_size,
                         num_devices, cores_per_device, xm, torch, num_nodes=1):
    """collective_permute: point-to-point send from src_stage to dst_stage."""
    stage = 0 if rank < half else 1
    stacked = torch.stack(activations, dim=0)
    if src_stage == 0:
        pairs = [[r, r + half] for r in range(half)]
    else:
        pairs = [[r + half, r] for r in range(half)]
    recv = xm.collective_permute(stacked, pairs)
    if stage == src_stage:
        result = stacked
    else:
        result = recv
    return [result[m] for m in range(M)]
